mod solution;

fn main() {
    let cases = [
    (r#"values=[7,13,11] random=[null,0,1]"#, r#"7:null,13:0,11:1"#),
    (r#"values=[1] random=[null]"#, r#"1:null"#),
    (r#"
values=[1] random=[null]
"#, r#"1:null"#),
    (r#"  
values=[7,13,11] random=[null,0,1]
  "#, r#"7:null,13:0,11:1"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS copy-random-list");
}
